//! Runs every case of `vectors/*.json` (generated by `gen-vectors`, SERVER_DESIGN §7 / §9 S1)
//! through the stateless ABI: `{"op": op, ...input}` → with `expect`, ok and every expected key
//! deep-equal in `result`; with `error`, `ok: false` with exactly that `code`.

use std::collections::BTreeSet;
use std::path::Path;

use ombra_core::api::call_stateless;
use serde_json::Value as J;

fn check(c: &J) -> Result<(), String> {
    let op = c["op"].as_str().ok_or("missing 'op'")?;
    let mut req = c["input"].as_object().ok_or("'input' must be an object")?.clone();
    if req.contains_key("op") { return Err("'input' uses the reserved key 'op'".into()); }
    req.insert("op".into(), J::String(op.into()));
    let r = call_stateless(J::Object(req));
    match (c.get("expect"), c.get("error")) {
        (Some(J::Object(exp)), None) => {
            if r["ok"] != J::Bool(true) { return Err(format!("expected ok, got {r}")); }
            for (k, v) in exp {
                if r["result"].get(k) != Some(v) { return Err(format!("result.{k} = {}, expected {v}", r["result"][k])); }
            }
            Ok(())
        }
        (None, Some(J::String(code))) => {
            if r["ok"] != J::Bool(false) || r["code"].as_str() != Some(code) { return Err(format!("expected error {code}, got {r}")); }
            Ok(())
        }
        _ => Err("case needs exactly one of 'expect' (object) or 'error' (string)".into()),
    }
}

#[test]
fn vectors_match_the_stateless_abi() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("vectors");
    let mut files: Vec<_> = std::fs::read_dir(&dir).expect("vectors/ directory").map(|e| e.unwrap().path())
        .filter(|p| p.extension().is_some_and(|x| x == "json")).collect();
    files.sort();
    assert!(!files.is_empty(), "no vector files in {}", dir.display());
    let (mut names, mut failures, mut total) = (BTreeSet::new(), vec![], 0);
    for f in &files {
        let file = f.file_name().unwrap().to_string_lossy().to_string();
        let doc: J = serde_json::from_str(&std::fs::read_to_string(f).unwrap()).unwrap_or_else(|x| panic!("{file}: {x}"));
        let cases = doc["cases"].as_array().unwrap_or_else(|| panic!("{file}: missing 'cases'"));
        assert!(!cases.is_empty(), "{file}: no cases");
        for c in cases {
            let name = c["name"].as_str().unwrap_or_else(|| panic!("{file}: case without name")).to_string();
            assert!(names.insert(name.clone()), "duplicate case name {name}");
            total += 1;
            if let Err(x) = check(c) { failures.push(format!("{file}/{name}: {x}")); }
        }
    }
    assert!(failures.is_empty(), "{} of {total} vector cases failed:\n{}", failures.len(), failures.join("\n"));
}
